/* Rivalries use stable franchise keys and recorded events, never invented league history. */
const RIVALRY_TYPES={geography:'Cross-Town Feud',founders:"Founders’ Clash",contrast:'Rust Belt vs. Coast Divide',heartbreak:'Heartbreak Repeat',grudge:"Enforcer’s Grudge",spoilsport:'The Spoilsport',return:'The Bitter Trade / The Return',draft:'Draft Class Duel',mentor:'Mentor vs. Protégé',regional:'Regional Rivalry'};
const RIVALRY_REGIONS={Atlanta:'GA',Savannah:'GA',Miami:'FL',Orlando:'FL',Tampa:'FL','New York':'NY',Brooklyn:'NY',Buffalo:'NY','Los Angeles':'CA',Sacramento:'CA','San Francisco':'CA','San Diego':'CA',Oakland:'CA',Memphis:'TN',Nashville:'TN',Dallas:'TX',Houston:'TX','San Antonio':'TX',Austin:'TX',Cleveland:'OH',Columbus:'OH',Cincinnati:'OH',Philadelphia:'PA',Pittsburgh:'PA',Seattle:'WA',Portland:'OR',Chicago:'IL',Detroit:'MI',Boston:'MA','New Orleans':'LA',Charlotte:'NC',Raleigh:'NC',Anaheim:'CA','San Jose':'CA',Newark:'NJ','East Rutherford':'NJ','Green Bay':'WI',Milwaukee:'WI','St. Louis':'MO','Kansas City':'MO',Toronto:'ON',Ottawa:'ON',Calgary:'AB',Winnipeg:'MB',Vancouver:'BC',Montreal:'QC'};
// Labels only: metro and same-state/province pairs keep the existing geography effects.
const RIVALRY_CANADA=new Set(['ON','AB','MB','BC','QC']);
const RIVALRY_SAME_CITY={Brooklyn:'New York'};
const RIVALRY_METROS={'Los Angeles':'Los Angeles',Anaheim:'Los Angeles',Inglewood:'Los Angeles','New York':'New York',Brooklyn:'New York',Newark:'New York','East Rutherford':'New York','San Francisco':'Bay Area',Oakland:'Bay Area','San Jose':'Bay Area'};
