const rivalryPlayBefore=play;play=function(a,b,stage='Regular season'){rivalrySyncPersonnel();const clubs=[state.teams[a],state.teams[b]],before=clubs.map(t=>({id:t.id,gp:t.w+t.l,pct:t.w/(t.w+t.l||1),streak:atmosphereForm(t).streak})),previous=activeRivalry;activeRivalry=rivalryMatchup(...clubs);const context=activeRivalry;try{const game=rivalryPlayBefore(a,b,stage);game.rivalry={badBlood:context.types.length?context.heat:1,types:[...new Set(context.types.map(e=>e.kind))],splitCrowd:context.split};rivalryAfterGame(...clubs,game,before,context);return game}finally{activeRivalry=previous}};
const rivalryAttributeBefore=effectiveAttribute;effectiveAttribute=function(p,key,progress,starter,bonus=0){return rivalryAttributeBefore(p,key,progress,starter,bonus+rivalryPlayerBonus(p))};
const rivalryInjuryBefore=durabilityInjuryChance;durabilityInjuryChance=function(...args){return Math.min(1,rivalryInjuryBefore(...args)*(1+(activeRivalry?.intensity||0)*.25))};
const rivalryIsolationBefore=isolationTrigger;isolationTrigger=function(p,d,club,clock,random=Math.random){if(activeRivalry?.returnGame&&random()<.2)return {reason:'rivalry return',post:false};return rivalryIsolationBefore(p,d,club,clock,random)};
function rivalriesPanel(t){rivalrySyncPersonnel();const rows=state.teams.filter(o=>o.key!==t.key).map(o=>({o,...rivalryDetails(t,o)})).filter(r=>r.types.length||r.events.length).sort((a,b)=>b.heat-a.heat),h2h=headToHeadRows(t);return gmPanel('RIVALRIES',`<p>Bad blood grows through local pride, postseason heartbreak and personnel drama. Effects apply only during the matchup; permanent player ratings do not change.</p><div class="rivalry-grid">${rows.map(r=>{const h=h2h.find(x=>x.team.key===r.o.key),next=state.schedule.slice(state.day).flatMap((pairs,i)=>pairs.some(p=>p.includes(t.id)&&p.includes(r.o.id))?[state.day+i]:[])[0];return `<article class="rivalry-card"><div class="panelhead"><h3>${secondaryTeamLogo(r.o)} ${escapeHTML(r.o.city+' '+r.o.name)}</h3><strong>${r.heat}/100</strong></div><meter min="1" max="100" value="${r.heat}" aria-label="Bad blood with ${escapeHTML(r.o.city)}">${r.heat}</meter><p>${r.types.length?[...new Set(r.types.map(e=>e.label||RIVALRY_TYPES[e.kind]))].map(escapeHTML).join(' · '):'Cooling rivalry · no active special effect'}</p><small>Regular season ${h.w}–${h.l} · Playoffs ${h.pw}–${h.pl}${next!==undefined?' · Next meeting: '+escapeHTML(scheduleDateLabel(next)):''}</small>${r.types.map(e=>`<p>${escapeHTML(e.text)}${e.remaining?' <strong>'+e.remaining+' eligible matchup'+(e.remaining===1?'':'s')+' remaining.</strong>':''}</p>`).join('')}<details><summary>Rivalry timeline (${r.events.length})</summary>${r.events.map(e=>`<p><small>${e.year} · Day ${e.day}</small><br>${escapeHTML(e.text)}</p>`).join('')||'<p>No recorded flashpoints yet.</p>'}</details></article>`}).join('')||'<p>No active rivalry yet. Local rivals appear automatically; new feuds emerge from the games and roster moves you record.</p>'}</div><details><summary>How rivalries affect games</summary><p>Bad blood raises technical/flagrant foul risk by up to 60%, with an additional 80% during an enforcer’s grudge. Existing two-technical and flagrant ejection rules still apply. General injury risk rises by up to 25%, respecting injury settings.</p><p>Revenge, draft rivals and former mentor relationships can raise effective skills; fiery players respond positively, while money-chasers and injury-prone players may struggle. Combined changes are capped at −2 to +5 skill points, scaled by intensity. Split local crowds cancel the normal home shooting edge; other rivalry crowds add up to 0.8 percentage points. A star’s first homecoming raises isolation frequency on both sides.</p><p>Founders’ clashes require two recorded Finals meetings between the earliest recorded franchises. Mentorship requires a recorded veteran leader/young reserve relationship followed by a leading role elsewhere. Unknown pre-career history is never invented. Tracking begins in ${rivalryStore().started}.</p></details>`);}
function readRivalries(raw,data,bad){
 if(raw===undefined)return {version:1,started:data.year,founders:data.teams.map(t=>t.key),pairs:[],players:data.teams.flatMap(t=>{const sorted=[...t.roster].sort((a,b)=>b.ovr-a.ovr);return t.roster.map(p=>({id:p.id,club:t.key,ovr:p.ovr,bench:sorted.indexOf(p)>=5,mentors:p.age<=25&&sorted.indexOf(p)>=5?t.roster.filter(q=>q.age>=30&&hasTrait(q,'leader')).slice(0,8).map(q=>q.id):[]}))})};
 const int=(n,l,h)=>Number.isInteger(n)&&n>=l&&n<=h,str=(s,n)=>typeof s==='string'&&s.length>0&&s.length<=n,keys=new Set(data.teams.map(t=>t.key));
 if(!raw||!Array.isArray(raw.founders)||raw.founders.length>36||raw.founders.some(k=>!keys.has(k))||raw.version!==1||!int(raw.started,1900,data.year)||!Array.isArray(raw.pairs)||raw.pairs.length>630||!Array.isArray(raw.players)||raw.players.length>3080)bad('invalid rivalries');
 const seen=new Set(),pairs=raw.pairs.map(r=>{const key=JSON.stringify([r?.a,r?.b]);if(!r||!keys.has(r.a)||!keys.has(r.b)||r.a>=r.b||seen.has(key)||!int(r.heat,1,100)||!int(r.lastYear,1900,data.year)||!int(r.meetings,0,1000000)||!Array.isArray(r.events)||r.events.length>80||r.announced!==undefined&&!str(r.announced,40))bad('invalid rivalry pair');seen.add(key);const ids=new Set();return {a:r.a,b:r.b,heat:r.heat,lastYear:r.lastYear,meetings:r.meetings,...(r.announced?{announced:r.announced}:{}),events:r.events.map(e=>{if(!e||!['elimination',...Object.keys(RIVALRY_TYPES)].includes(e.kind)||!str(e.id,200)||ids.has(e.id)||!str(e.text,600)||!int(e.year,1900,data.year)||!int(e.day,1,367)||!int(e.remaining,0,5)||!Array.isArray(e.players)||e.players.length>8||e.players.some(id=>!int(id,0,10000000))||e.target!==undefined&&![r.a,r.b].includes(e.target)||e.winner!==undefined&&![r.a,r.b].includes(e.winner)||e.final!==undefined&&typeof e.final!=='boolean')bad('invalid rivalry event');ids.add(e.id);return {kind:e.kind,id:e.id,text:e.text,year:e.year,day:e.day,remaining:e.remaining,players:[...e.players],...Object.fromEntries(['target','winner','final'].filter(k=>e[k]!==undefined).map(k=>[k,e[k]]))}})}});
 const ids=new Set(),players=raw.players.map(p=>{if(!p||!int(p.id,0,10000000)||ids.has(p.id)||!keys.has(p.club)||!int(p.ovr,1,99)||typeof p.bench!=='boolean'||!Array.isArray(p.mentors)||p.mentors.length>8||p.mentors.some(id=>!int(id,0,10000000)))bad('invalid rivalry personnel');ids.add(p.id);return {id:p.id,club:p.club,ovr:p.ovr,bench:p.bench,mentors:[...p.mentors]}});return {version:1,started:raw.started,founders:[...raw.founders],pairs,players};
}
const rivalryValidateBefore=validateCareerData;validateCareerData=function(raw){const data=rivalryValidateBefore(raw),bad=msg=>{throw Error('Invalid save: '+msg)};data.rivalries=readRivalries(raw.rivalries,data,bad);for(let i=0;i<data.history.length;i++){const r=raw.history[i].rivalry;if(r!==undefined){if(!r||!Number.isInteger(r.badBlood)||r.badBlood<1||r.badBlood>100||typeof r.splitCrowd!=='boolean'||!Array.isArray(r.types)||r.types.length>9||r.types.some(k=>!Object.hasOwn(RIVALRY_TYPES,k)))bad('invalid rivalry game snapshot');data.history[i].rivalry={badBlood:r.badBlood,types:[...r.types],splitCrowd:r.splitCrowd}}}return data};
const rivalrySaveBefore=save;save=function(...args){if(state?.teams)rivalrySyncPersonnel();return rivalrySaveBefore(...args)};
const rivalryDayBefore=ownerDay;ownerDay=function(...args){const result=rivalryDayBefore(...args);rivalrySyncPersonnel();const fixture=state.schedule.slice(state.day,state.day+14).flatMap((pairs,i)=>pairs.filter(p=>p.includes(controlledTeamId())).map(pair=>({pair,day:state.day+i}))).find(f=>rivalryDetails(...f.pair.map(id=>state.teams[id])).types.length);if(fixture){const [a,b]=fixture.pair.map(id=>state.teams[id]),d=rivalryDetails(a,b),r=rivalryPair(a,b,true),stamp=state.year+':'+fixture.day;if(r.announced!==stamp){r.announced=stamp;addNewsItem({category:'Franchise',headline:'Rivalry watch: '+a.city+' vs. '+b.city,detail:d.types.map(e=>e.text).join(' ').slice(0,1000),teams:fixture.pair})}}return result};
